		ClassTranslator.put("ghidra.app.util.bin.format.microsoft.GuidDataType",
			typeof(GuidDataType).getName());
	}

	/**
	 * Provides a definition of a GUID within a program.
	 */
	private static long serialVersionUID = 1;
	private static readonly string NAME = "GUID";

	private static readonly EndianSettingsDefinition ENDIAN = EndianSettingsDefinition.DEF;
	private static SettingsDefinition[] SETTINGS_DEFS = { ENDIAN };

	public static readonly int SIZE = 16;
	public static readonly int ALIGNMENT = 4;
	public static readonly string KEY = "GUID_NAME";

	private static string cachedGuidString;
	private static string cachedGuidName;

	/**
	 * Creates a Double Word data type.
	 */
	public GuidDataType() : this(null)
    {
	}

	public GuidDataType(DataTypeManager dtm) : base(null, NAME, dtm)
    {
	}

